1	const { parse_expression } = require("./parse_expression");
2	
3	let passed = 0;
4	let failed = 0;
5	
6	function assert(condition, label) {
7	  if (condition) {
8	    passed++;
9	  } else {
10	    failed++;
11	    console.log(`FAIL: ${label}`);
12	  }
13	}
14	
15	// ── Constructor validation ───────────────────────────────────────────────────
16	
17	assert(
18	  (() => { try { parse_expression(0, 1000); return false; } catch (e) { return e instanceof RangeError; } })(),
19	  "maxRequests < 1 throws RangeError"
20	);
21	
22	assert(
23	  (() => { try { parse_expression(-1, 1000); return false; } catch (e) { return e instanceof RangeError; } })(),
24	  "negative maxRequests throws RangeError"
25	);
26	
27	assert(
28	  (() => { try { parse_expression(5, 0); return false; } catch (e) { return e instanceof RangeError; } })(),
29	  "windowMs < 1 throws RangeError"
30	);
31	
32	assert(
33	  (() => { try { parse_expression(5, -100); return false; } catch (e) { return e instanceof RangeError; } })(),
34	  "negative windowMs throws RangeError"
35	);
36	
37	assert(
38	  (() => { try { parse_expression(NaN, 1000); return false; } catch (e) { return e instanceof RangeError; } })(),
39	  "NaN maxRequests throws RangeError"
40	);
41	
42	// ── Basic allow / deny ──────────────────────────────────────────────────────
43	
44	{
45	  const limiter = parse_expression(3, 1000);
46	  assert(limiter(0) === true,  "1st request allowed at t=0");
47	  assert(limiter(100) === true, "2nd request allowed at t=100");
48	  assert(limiter(200) === true, "3rd request allowed at t=200");
49	  assert(limiter(300) === false, "4th request denied at t=300");
50	  assert(limiter(400) === false, "5th request denied at t=400");
51	}
52	
53	// ── Window expiry frees slots ───────────────────────────────────────────────
54	
55	{
56	  const limiter = parse_expression(2, 1000);
57	  assert(limiter(0) === true,    "1st allowed at t=0");
58	  assert(limiter(500) === true,  "2nd allowed at t=500");
59	  assert(limiter(900) === false, "3rd denied at t=900 (still in window)");
60	
61	  // At t=1001 the first entry (t=0) falls outside [1001-1000, 1001] = [1, 1001]
62	  assert(limiter(1001) === true, "allowed after first entry expires");
63	  assert(limiter(1002) === false, "denied again — second slot still occupied (t=500+1000=1500 > 1002)");
64	}
65	
66	// ── Exact boundary: entry at windowStart is evicted ─────────────────────────
67	
68	{
69	  const limiter = parse_expression(1, 100);
70	  assert(limiter(100) === true,  "allowed at t=100");
71	  // windowStart = 200 - 100 = 100; timestamp 100 <= 100 → evicted
72	  assert(limiter(200) === true,  "allowed at t=200 (boundary eviction)");
73	}
74	
75	// ── All requests within a tight burst ───────────────────────────────────────
76	
77	{
78	  const limiter = parse_expression(5, 100);
79	  for (let i = 0; i < 5; i++) {
80	    assert(limiter(1000 + i) === true, `burst request ${i + 1} allowed`);
81	  }
82	  assert(limiter(1005) === false, "6th burst request denied");
83	}
84	
85	// ── Requests spread across two windows ──────────────────────────────────────
86	
87	{
88	  const limiter = parse_expression(3, 1000);
89	  // First window
90	  assert(limiter(0) === true,    "spread: allowed t=0");
91	  assert(limiter(500) === true,  "spread: allowed t=500");
92	  assert(limiter(999) === true,  "spread: allowed t=999");
93	  // At t=1000 the entry at t=0 has expired (t=0 + 1000 = 1000, evicted by <=)
94	  assert(limiter(1000) === true,  "spread: allowed t=1000 (t=0 expired)");
95	  assert(limiter(1001) === false, "spread: denied t=1001 (500, 999, 1000 in window)");
96	  assert(limiter(1002) === false, "spread: denied t=1002");
97	}
98	
99	// ── High volume, verify count stays bounded ─────────────────────────────────
100	
101	{
102	  const limiter = parse_expression(10, 5000);
103	  let allowed = 0;
104	  for (let t = 0; t < 10000; t += 100) {
105	    if (limiter(t)) allowed++;
106	  }
107	  // At any point we should never exceed 10 in a 5 s window.
108	  // The exact allowed count depends on window sliding, but it must be >= 10.
109	  assert(allowed >= 10, `high volume: allowed=${allowed}, expected >= 10`);
110	}
111	
112	// ── Separate limiters are independent ───────────────────────────────────────
113	
114	{
115	  const a = parse_expression(1, 1000);
116	  const b = parse_expression(1, 1000);
117	  assert(a(0) === true, "limiter A allowed");
118	  assert(b(0) === true, "limiter B allowed (independent)");
119	  assert(a(0) === false, "limiter A denied on reuse");
120	}
121	
122	// ── Edge: maxRequests = 1 ───────────────────────────────────────────────────
123	
124	{
125	  const limiter = parse_expression(1, 1000);
126	  assert(limiter(0) === true, "single-slot allowed");
127	  assert(limiter(500) === false, "single-slot denied before expiry");
128	  assert(limiter(1000) === true, "single-slot allowed after window");
129	}
130	
131	// ── Edge: windowMs = 1 (smallest) ───────────────────────────────────────────
132	
133	{
134	  const limiter = parse_expression(2, 1);
135	  assert(limiter(100) === true, "tiny window: 1st allowed");
136	  assert(limiter(100) === true, "tiny window: 2nd allowed (same ms)");
137	  assert(limiter(100) === false, "tiny window: 3rd denied (same ms)");
138	  assert(limiter(101) === true, "tiny window: allowed at t=101 (expired)");
139	}
140	
141	// ── Non-numeric `now` falls back to Date.now ────────────────────────────────
142	
143	{
144	  const limiter = parse_expression(100, 60000);
145	  // Call without a timestamp — should not throw
146	  const result = limiter();
147	  assert(result === true, "no timestamp arg: uses Date.now, returns boolean");
148	}
149	
150	// ── Summary ──────────────────────────────────────────────────────────────────
151	
152	console.log(`\n${passed + failed} tests, ${passed} passed, ${failed} failed`);
153	process.exit(failed > 0 ? 1 : 0);
154

