/**
 * Thread pool for parallel async task execution on the Node.js event loop.
 *
 * Tasks are queued in a bounded buffer and executed up to `concurrency`
 * at a time. Each submitted task returns a Promise that resolves/rejects
 * with the task's result.
 *
 * @param {number} [concurrency=4]        - max simultaneous tasks
 * @param {number} [queueCapacity=1024]   - max queued tasks before rejection
 * @returns {{ submit: Function, drain: Function, close: Function,
 *             running: number, queued: number, concurrency: number }}
 */
function parse_expression(concurrency = 4, queueCapacity = 1024) {
  if (!Number.isInteger(concurrency) || concurrency < 1) {
    throw new RangeError("concurrency must be a positive integer");
  }
  if (!Number.isInteger(queueCapacity) || queueCapacity < 1) {
    throw new RangeError("queueCapacity must be a positive integer");
  }

  let running = 0;
  let closed = false;
  let drainResolve = null;
  const queue = [];

  function run(task) {
    running++;
    Promise.resolve()
      .then(() => task.fn())
      .then(
        (val) => { task.resolve(val); finish(); },
        (err) => { task.reject(err); finish(); }
      );
  }

  function finish() {
    running--;
    if (queue.length > 0) {
      run(queue.shift());
    } else if (running === 0 && drainResolve) {
      drainResolve();
      drainResolve = null;
    }
  }

  /**
   * Submit an async function for execution.
   * @param {Function} fn - async function (or sync returning a value)
   * @returns {Promise} resolves/rejects with the task result
   */
  function submit(fn) {
    if (closed) throw new Error("pool is closed");
    if (typeof fn !== "function") throw new TypeError("fn must be a function");
    if (running >= concurrency && queue.length >= queueCapacity) {
      throw new Error("queue is full");
    }

    return new Promise((resolve, reject) => {
      const task = { fn, resolve, reject };
      if (running < concurrency) {
        run(task);
      } else {
        queue.push(task);
      }
    });
  }

  /**
   * Wait until all submitted tasks have finished.
   * @returns {Promise}
   */
  function drain() {
    if (running === 0 && queue.length === 0) return Promise.resolve();
    return new Promise((resolve) => { drainResolve = resolve; });
  }

  /**
   * Reject queued tasks, wait for in-flight to finish.
   * @returns {Promise}
   */
  async function close() {
    closed = true;
    while (queue.length > 0) {
      const t = queue.shift();
      t.reject(new Error("pool closed before execution"));
    }
    await drain();
  }

  return {
    submit,
    drain,
    close,
    get running() { return running; },
    get queued() { return queue.length; },
    get concurrency() { return concurrency; },
  };
}

module.exports = { parse_expression };

const { parse_expression } = require("./parse_expression");

let passed = 0;
let failed = 0;

function assert(condition, label) {
  if (condition) {
    passed++;
  } else {
    failed++;
    console.log(`  FAIL: ${label}`);
  }
}

async function assertThrows(fn, errorType, label) {
  try {
    await fn();
    failed++;
    console.log(`  FAIL: ${label} (no error thrown)`);
  } catch (e) {
    assert(e instanceof errorType, label);
  }
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

// ── Constructor validation ─────────────────────────────────────────────────

assertThrows(() => parse_expression(0), RangeError, "concurrency=0 throws RangeError");
assertThrows(() => parse_expression(-1), RangeError, "negative concurrency throws RangeError");
assertThrows(() => parse_expression(1.5), RangeError, "float concurrency throws RangeError");
assertThrows(() => parse_expression(NaN), RangeError, "NaN concurrency throws RangeError");
assertThrows(() => parse_expression(4, 0), RangeError, "queueCapacity=0 throws RangeError");
assertThrows(() => parse_expression(4, -1), RangeError, "negative queueCapacity throws RangeError");

// ── Basic properties ───────────────────────────────────────────────────────

{
  const pool = parse_expression(3, 10);
  assert(pool.concurrency === 3, "concurrency getter returns 3");
  assert(pool.running === 0, "initial running is 0");
  assert(pool.queued === 0, "initial queued is 0");
}

// ── Submit and resolve ─────────────────────────────────────────────────────

{
  const pool = parse_expression(2);
  const p = pool.submit(() => 42);
  assert(p instanceof Promise, "submit returns a Promise");
  p.then((val) => {
    assert(val === 42, "sync task resolves with value");
  });
}

// ── Async task resolution ──────────────────────────────────────────────────

{
  const pool = parse_expression(2);
  pool.submit(async () => {
    await sleep(10);
    return "hello";
  }).then((val) => {
    assert(val === "hello", "async task resolves");
  });
}

// ── Task rejection ─────────────────────────────────────────────────────────

{
  const pool = parse_expression(2);
  pool.submit(() => { throw new Error("boom"); }).then(
    () => { failed++; console.log("  FAIL: sync throw should reject"); },
    (err) => { assert(err.message === "boom", "sync throw rejects with error"); }
  );
}

{
  const pool = parse_expression(2);
  pool.submit(async () => { throw new Error("async-boom"); }).then(
    () => { failed++; console.log("  FAIL: async throw should reject"); },
    (err) => { assert(err.message === "async-boom", "async throw rejects with error"); }
  );
}

// ── Concurrency limiting ───────────────────────────────────────────────────

{
  const pool = parse_expression(2);
  let maxConcurrent = 0;
  let current = 0;

  function slowTask() {
    current++;
    maxConcurrent = Math.max(maxConcurrent, current);
    return sleep(50).then(() => { current--; });
  }

  Promise.all([
    pool.submit(slowTask),
    pool.submit(slowTask),
    pool.submit(slowTask),
    pool.submit(slowTask),
  ]).then(() => {
    assert(maxConcurrent <= 2, `concurrency capped at 2 (was ${maxConcurrent})`);
  });
}

// ── Queue fills up ─────────────────────────────────────────────────────────

{
  const pool = parse_expression(1, 2);
  // Fill the 1 running slot + 2 queue slots, 4th should throw
  pool.submit(() => sleep(100));
  pool.submit(() => sleep(100));
  pool.submit(() => sleep(100));
  try {
    pool.submit(() => sleep(100));
    failed++;
    console.log("  FAIL: should throw when queue is full");
  } catch (e) {
    assert(e.message === "queue is full", "throws when queue is full");
  }
}

// ── Submit after close ─────────────────────────────────────────────────────

{
  const pool = parse_expression(2);
  pool.close().then(() => {
    try {
      pool.submit(() => 1);
      failed++;
      console.log("  FAIL: submit after close should throw");
    } catch (e) {
      assert(e.message === "pool is closed", "throws after close");
    }
  });
}

// ── Submit non-function ────────────────────────────────────────────────────

{
  const pool = parse_expression(2);
  try {
    pool.submit("not a function");
    failed++;
    console.log("  FAIL: submit non-function should throw");
  } catch (e) {
    assert(e instanceof TypeError, "submit non-function throws TypeError");
  }
}

// ── Drain waits for all tasks ──────────────────────────────────────────────

{
  const pool = parse_expression(2);
  const results = [];

  pool.submit(async () => { await sleep(30); results.push("a"); });
  pool.submit(async () => { await sleep(10); results.push("b"); });
  pool.submit(async () => { await sleep(20); results.push("c"); });

  pool.drain().then(() => {
    assert(results.length === 3, `drain: all 3 tasks finished (${results.length})`);
    assert(pool.running === 0, "drain: running is 0");
    assert(pool.queued === 0, "drain: queued is 0");
  });
}

// ── Drain resolves immediately when empty ──────────────────────────────────

{
  const pool = parse_expression(2);
  let resolved = false;
  pool.drain().then(() => { resolved = true; });
  // drain on an empty pool should resolve on next microtick
  setTimeout(() => {
    assert(resolved === true, "drain on empty pool resolves");
  }, 10);
}

// ── Close rejects queued tasks ─────────────────────────────────────────────

{
  const pool = parse_expression(1, 10);
  const errors = [];

  // One fills the running slot; the others queue
  pool.submit(() => sleep(50)).catch(() => {});
  const p2 = pool.submit(() => sleep(50)).catch((e) => errors.push(e));
  const p3 = pool.submit(() => sleep(50)).catch((e) => errors.push(e));

  // Close immediately — p2 and p3 are still queued
  pool.close();

  Promise.all([p2.catch(() => {}), p3.catch(() => {})]).then(() => {
    assert(errors.length === 2, `close: queued tasks rejected (${errors.length})`);
    assert(
      errors.every((e) => e.message === "pool closed before execution"),
      "close: rejection message correct"
    );
  });
}

// ── Multiple tasks complete in order of resolution (not submission) ────────

{
  const pool = parse_expression(3);
  const order = [];

  pool.submit(async () => { await sleep(40); order.push(1); });
  pool.submit(async () => { await sleep(10); order.push(2); });
  pool.submit(async () => { await sleep(20); order.push(3); });

  pool.drain().then(() => {
    assert(
      order[0] === 2 && order[1] === 3 && order[2] === 1,
      `tasks finish in resolution order: [${order}]`
    );
  });
}

// ── Large batch, verify all resolve ────────────────────────────────────────

{
  const pool = parse_expression(8, 200);
  const promises = [];
  for (let i = 0; i < 100; i++) {
    promises.push(pool.submit(() => i * 2));
  }
  Promise.all(promises).then((results) => {
    assert(results.length === 100, "100 tasks all resolved");
    assert(results[0] === 0 && results[50] === 100 && results[99] === 198, "results are correct");
  });
}

// ── Tasks submitted during execution get picked up ─────────────────────────

{
  const pool = parse_expression(1);
  const order = [];

  pool.submit(async () => {
    order.push("first");
    // Submit a new task while the first is still running
    pool.submit(async () => { order.push("second"); });
    await sleep(10);
  });

  pool.drain().then(() => {
    assert(order[0] === "first" && order[1] === "second", `chained: [${order}]`);
  });
}

// ── Summary (delayed to let async tests finish) ────────────────────────────

setTimeout(() => {
  console.log(`\n${passed + failed} tests, ${passed} passed, ${failed} failed`);
  process.exit(failed > 0 ? 1 : 0);
}, 500);
